package com.bank.hop.service;

import java.util.Arrays;
import java.util.logging.Logger;

// Finds the fewest hops to reach the last stage given per-stage reach.
public class PipelineHopService {
    private static final Logger log = Logger.getLogger(PipelineHopService.class.getName());

    public int minJumps(int[] reach) {
        int n = reach.length;
        int[] jumps = new int[n];
        Arrays.fill(jumps, Integer.MAX_VALUE);
        jumps[0] = 0;                               // start needs no hops
        for (int i = 1; i < n; i++) {
            for (int j = 0; j < i; j++) {
                // j can hop to i if its reach covers i and j is itself reachable.
                if (j + reach[j] >= i && jumps[j] != Integer.MAX_VALUE) {
                    jumps[i] = Math.min(jumps[i], jumps[j] + 1);
                }
            }
        }
        int result = jumps[n - 1] == Integer.MAX_VALUE ? -1 : jumps[n - 1];
        final int r = result;
        log.info(() -> "Fewest hops to last stage = " + r);
        return result;
    }
}
