package com.bank.hop;

import com.bank.hop.service.PipelineHopService;
import java.util.logging.Logger;

public class PipelineHopApplication {
    private static final Logger log = Logger.getLogger(PipelineHopApplication.class.getName());

    public static void main(String[] args) {
        PipelineHopService service = new PipelineHopService();
        int[] reach = {2, 1, 1, 1, 4};      // max hop length from each stage
        int hops = service.minJumps(reach);
        log.info("Minimum hops across the pipeline: " + hops);
    }
}
